 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Components are the separate 1-colored shapes; fill each component's
    # bounding box with 3 (except its 1s) and surround the box with a 1-cell 2 halo.
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            comps.append(cells)
    out=[row[:] for row in grid]
    for cells in comps:
        r0=min(y for y,x in cells); r1=max(y for y,x in cells)
        c0=min(x for y,x in cells); c1=max(x for y,x in cells)
        # Inner area of bounding rectangle is colored 3; frame around box is 2.
        for y in range(r0+1,r1):
            for x in range(c0+1,c1):
                if grid[y][x]==0: out[y][x]=3
        for y in range(max(0,r0-1),min(h,r1+2)):
            for x in range(max(0,c0-1),min(w,c1+2)):
                if y in (r0-1,r1+1) or x in (c0-1,c1+1):
                    if grid[y][x]==0: out[y][x]=2
    return out

