    # whose border contains small gaps/overlapping 1 marks. Locate rectangles
    # by checking whether zero cells are fully enclosed by foreground.
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    interior = [(r, c) for r in range(r0 + 1, r1)
                                for c in range(c0 + 1, c1) if grid[r][c] == 0]
                    if len(interior) < 2:
                        continue
                    # For a candidate frame, require at least 70% of its
                    # perimeter to be 1 and a majority of its interior blank.
                    per = ([(r0, c) for c in range(c0, c1 + 1)] +
                           [(r1, c) for c in range(c0, c1 + 1)] +
                           [(r, c0) for r in range(r0 + 1, r1)] +
                           [(r, c1) for r in range(r0 + 1, r1)])
                    if sum(grid[r][c] == 1 for r, c in per) < 0.70 * len(per):
                        continue
                    if sum(grid[r][c] == 0 for r, c in interior) < 0.60 * len(interior):
                        continue
                    # Frames that have already been produced are not relevant;
                    # draw colors only where the original canvas is background.
                    for r, c in interior:
