def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 1-components so a discovered enclosed zero region can be associated
    # with the contour(s) surrounding it.
    fg_seen = set()
    fg_components = []
    fg_label = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in fg_seen:
                continue
            q = deque([(r, c)])
            fg_seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in fg_seen:
                        fg_seen.add((ny, nx))
                        q.append((ny, nx))
            idx = len(fg_components)
            fg_components.append(cells)
            for cell in cells:
                fg_label[cell] = idx

    # A cavity is a 4-connected zero component that cannot reach the canvas edge.
    bg_seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in bg_seen:
                continue
            q = deque([(r, c)])
            bg_seen.add((r, c))
            cavity = []
            touches_edge = False
            owners = set()
            edge_cells = set()
            while q:
                y, x = q.popleft()
                cavity.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w):
                        touches_edge = True
                    elif grid[ny][nx] == 0:
                        if (ny, nx) not in bg_seen:
                            bg_seen.add((ny, nx))
                            q.append((ny, nx))
                    else:
                        owners.add(fg_label[(ny, nx)])
                        edge_cells.add((y, x))
            if touches_edge or not owners:
                continue

            # Only the inner rim is colored: the core remains zero.
            for y, x in edge_cells:
                out[y][x] = 3

