def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Detect axis-aligned rectangular frames with exactly one missing perimeter
    # pixel. The missing pixel is the intentional opening; completely closed
    # and heavily broken contours are left alone.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = ({(r0,x) for x in range(c0,c1+1)} |
                         {(r1,x) for x in range(c0,c1+1)} |
                         {(y,c0) for y in range(r0,r1+1)} |
                         {(y,c1) for y in range(r0,r1+1)})
            gaps = perimeter - set(cells)
            if len(gaps) != 1:
                continue
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if grid[y][x] == 0:
                        out[y][x] = 3
            for y in range(r0-1,r1+2):
                for x in range(c0-1,c1+2):
                    if (0 <= y < h and 0 <= x < w and
                        (y in (r0-1,r1+1) or x in (c0-1,c1+1)) and
                        grid[y][x] == 0):
                        out[y][x] = 2
    return out
