G=[list(map(int,l.split())) for l in open('/tmp/test_input.txt') if l.strip()]
h,w=len(G),len(G[0]);out=[row[:] for row in G]
# Fill all true holes enclosed by 1s; retain one center zero for holes of odd area.
seen=set()
for r in range(h):
 for c in range(w):
  if G[r][c]!=0 or (r,c) in seen:continue
  stack=[(r,c)];seen.add((r,c));reg=[];edge=False; touches=set()
  while stack:
   y,x=stack.pop();reg.append((y,x))
   if y in (0,h-1) or x in (0,w-1):edge=True
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=y+dy,x+dx
    if not(0<=ny<h and 0<=nx<w):edge=True
    elif G[ny][nx]==0:
     if (ny,nx) not in seen:seen.add((ny,nx));stack.append((ny,nx))
    else:touches.add((ny,nx))
  if edge or not touches:continue
  for y,x in reg:out[y][x]=3
  # The input hollow sometimes contains 1-strokes crossing the hole; leave them intact.
  if len(reg)%2==1:
   # retain the most central zero cell
   cy=(min(y for y,x in reg)+max(y for y,x in reg))/2
   cx=(min(x for y,x in reg)+max(x for y,x in reg))/2
   y,x=min(reg,key=lambda p:(p[0]-cy)**2+(p[1]-cx)**2)
   out[y][x]=0
