def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label each connected foreground outline, retaining its full bounding box.
    seen1 = set()
    components = []
    label = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen1:
                continue
            q = deque([(r, c)])
            seen1.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny, nx) not in seen1:
                        seen1.add((ny, nx))
                        q.append((ny, nx))
            idx = len(components)
            components.append(cells)
            for cell in cells:
                label[cell] = idx

    # An enclosed background component is a hollow part of an outlined figure.
    # Paint the inner rim in 3, preserve its deeper core, and add a 2 frame just
    # outside the enclosing foreground component's bounding box.
    seen0 = set()
    framed = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen0:
                continue
            q = deque([(r, c)])
            seen0.add((r, c))
            region = []
            rim = set()
            owners = set()
            edge = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w):
                        edge = True
                    elif grid[ny][nx] == 0:
                        if (ny, nx) not in seen0:
                            seen0.add((ny, nx))
                            q.append((ny, nx))
                    else:
                        rim.add((y, x))
                        owners.add(label[(ny, nx)])
            if edge or not owners:
                continue
            for y, x in rim:
                out[y][x] = 3
            framed.update(owners)

    for idx in framed:
        cells = components[idx]
        r0 = min(y for y, x in cells)
        r1 = max(y for y, x in cells)
        c0 = min(x for y, x in cells)
        c1 = max(x for y, x in cells)
        for y in range(r0 - 1, r1 + 2):
            for x in range(c0 - 1, c1 + 2):
                if (0 <= y < h and 0 <= x < w and
                    (y in (r0 - 1, r1 + 1) or x in (c0 - 1, c1 + 1)) and
                    grid[y][x] == 0):
                    out[y][x] = 2
    return out
